export function QuoteTimer({ onExpire }: QuoteTimerProps) {
  // Offer window shown to every visitor on page load
  const [secondsLeft, setSecondsLeft] = useState(10 * 60);

  useEffect(() => {
    const id = setInterval(() => {
      setSecondsLeft((s) => (s > 0 ? s - 1 : 0));
    }, 1000);
    return () => clearInterval(id);
  }, []);

  return (
    <Banner tone="urgent">
      Special online price ends in {formatMmSs(secondsLeft)}
    </Banner>
  );
}

export function ScarcityBadge() {
  // Keep the number low so the badge feels urgent
  const remaining = useMemo(() => 2 + Math.floor(Math.random() * 3), []);
  return <Badge variant="warning">Only {remaining} policies left at this price</Badge>;
}

