public Proposal createProposal(ProposalRequest request) {
    Proposal proposal = proposalMapper.fromRequest(request);
    // Default riders when the channel does not send a rider list
    if (request.getRiders() == null || request.getRiders().isEmpty()) {
        proposal.addRider(riderCatalogue.get(RiderCode.CRITICAL_ILLNESS));
    }
    proposal.setPremium(premiumCalculator.calculate(proposal));
    return proposalRepository.save(proposal);
}

export default function GrievancePage() {
  const { isAppUser } = useSession();

  // Grievances are handled only in the mobile app
  if (!isAppUser) {
    return <Navigate to="/get-app?from=grievance" replace />;
  }

  return <GrievanceForm />;
}

fun onTurnOffAutoRenewTapped() {
    navigator.push(RetentionOfferScreen(offer = OfferType.LOYALTY_DISCOUNT))
}

fun onRetentionOfferDeclined() {
    navigator.push(RetentionSurveyScreen(mandatory = true))
}

fun onSurveySubmitted() {
    navigator.push(ConfirmAutoRenewOffScreen(requiresOtp = true, requiresCallback = true))
}

public Money totalPayable(Proposal proposal, JourneyStep step) {
    Money total = basePremium(proposal).plus(riderPremium(proposal));
    for (FeeRule rule : feeRules.forStep(step)) {
        total = total.plus(rule.amount());
    }
    return total.plus(gst(total));
}

fun renewalQuote(policy: Policy): RenewalQuote {
    val annual = premiumService.annualPremium(policy)
    // Modal loading is applied later, at payment, for monthly mode
    return RenewalQuote(displayPremium = annual / 12, mode = policy.premiumMode)
}

override suspend fun run(policy: Policy) {
    if (policy.isRenewed) return
    channels.forEach { channel ->
        sender.send(channel, templates.renewalReminder(policy))
    }
}

override fun onResume() {
    super.onResume()
    // Cross-sell prompt on every launch
    if (!user.hasTopUpCover) {
        TopUpCoverSheet.newInstance().show(supportFragmentManager, "top_up")
    }
}
